window.BOOKLET_DATA=[{"number":1,"title":{"en":"Cover","zh":"封面"},"width":1190.25,"height":842.25,"boxes":[{"text":"Portfolio of\nPhotojournalism\nCourses","rect":[586,43,1160,247],"size":79,"color":"#ccc025","family":"serif","align":"left","vertical":false},{"text":"09.09–12.25","rect":[912,189,1148,239],"size":45,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"20\n24","rect":[884,194,908,234],"size":19,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"Defining space\nthrough time","rect":[605,306,1144,405],"size":60,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Photojournalism: from introduction to exploration","rect":[605,442,1131,486],"size":33,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"From introduction to exploration","rect":[605,495,1000,521],"size":21,"color":"#ccc025","family":"serif","align":"left","vertical":false},{"text":"An art embedded in time","rect":[16,298,65,706],"size":29,"color":"#1e1e1e","family":"serif","align":"left","vertical":true},{"text":"The world is three-dimensional.\nAll you can do is change your angle of view.","rect":[107,614,511,706],"size":24,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"The author","rect":[610,617,690,641],"size":17,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"ABOUT THE AUTHOR","rect":[696,620,930,640],"size":18,"color":"#ccc025","family":"sans","align":"left","vertical":false},{"text":"Name: Huimin Wu\nProgramme: Journalism, Class 2201\nSchool: Media and International Culture","rect":[605,646,1050,735],"size":16,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"Instructors: Shen Bin · Qiu Huang\nProduced for the Photojournalism course","rect":[610,794,1160,829],"size":18,"color":"#111111","family":"sans","align":"left","vertical":false}],"transcript":{"en":["Portfolio of\nPhotojournalism\nCourses","09.09–12.25","20\n24","Defining space\nthrough time","Photojournalism: from introduction to exploration","From introduction to exploration","An art embedded in time","The world is three-dimensional.\nAll you can do is change your angle of view.","The author","ABOUT THE AUTHOR","Name: Huimin Wu\nProgramme: Journalism, Class 2201\nSchool: Media and International Culture","Instructors: Shen Bin · Qiu Huang\nProduced for the Photojournalism course"],"zh":["Portfolio of\nPhotojournalism\nCourses\n09.09-12.25\n20\n24","ABOUT THE AUTHOUR","【姓        名】吴慧敏\n【专        业】新闻2201\n【学        院】传媒与国际文化学院","作者介绍","From introduction to exploration\n——新聞攝影从入门到探究\n用時間定義空間\n嵌\n入\n時\n光\n的\n藝\n術","指导老师：沈斌 仇璜\n出品单位：新闻摄影课程","世界是立体的，你能做到的，仅","仅是改变一下观看的角度。"]},"publicZhBoxes":[{"text":"Portfolio of\nPhotojournalism\nCourses","rect":[586,43,1160,247],"size":79,"color":"#ccc025","family":"serif","align":"left","vertical":false},{"text":"09.09–12.25","rect":[912,189,1148,239],"size":45,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"20\n24","rect":[884,194,908,234],"size":19,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"用時間定義空間","rect":[605,306,1144,405],"size":60,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"——新聞攝影从入门到探究","rect":[605,442,1131,486],"size":33,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"From introduction to exploration","rect":[605,495,1000,521],"size":21,"color":"#ccc025","family":"serif","align":"left","vertical":false},{"text":"嵌入時光的藝術","rect":[16,298,65,706],"size":29,"color":"#1e1e1e","family":"serif","align":"left","vertical":true},{"text":"世界是立体的，你能做到的，仅仅是改变一下观看的角度。","rect":[107,614,511,706],"size":24,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"作者介绍","rect":[610,617,690,641],"size":17,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"ABOUT THE AUTHOR","rect":[696,620,930,640],"size":18,"color":"#ccc025","family":"sans","align":"left","vertical":false},{"text":"【姓        名】吴慧敏\n【专        业】新闻2201\n【学        院】传媒与国际文化学院","rect":[605,646,1050,735],"size":16,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"指导老师：沈斌 仇璜\n出品单位：新闻摄影课程","rect":[610,794,1160,829],"size":18,"color":"#111111","family":"sans","align":"left","vertical":false}]},{"number":2,"title":{"en":"Foreword & contents","zh":"卷首语与目录"},"width":1190.25,"height":842.25,"boxes":[{"text":"Foreword","rect":[10,15,300,125],"size":65,"color":"#887464","family":"serif","align":"left","vertical":false},{"text":"Contents","rect":[841,57,1120,115],"size":52,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Contents","rect":[918,750,1179,808],"size":48,"color":"#ddd","family":"serif","align":"left","vertical":false},{"text":"01","rect":[700,150,760,200],"size":45,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"News","rect":[815,150,1115,200],"size":32,"color":"#fff","family":"serif","align":"right","vertical":false},{"text":"02","rect":[700,226,760,276],"size":45,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Lines","rect":[815,226,1115,276],"size":32,"color":"#fff","family":"serif","align":"right","vertical":false},{"text":"03","rect":[700,299,760,349],"size":45,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Composition","rect":[815,299,1115,349],"size":32,"color":"#fff","family":"serif","align":"right","vertical":false},{"text":"04","rect":[700,376,760,426],"size":45,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Campus","rect":[815,376,1115,426],"size":32,"color":"#fff","family":"serif","align":"right","vertical":false},{"text":"05","rect":[700,449,760,499],"size":45,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Society","rect":[815,449,1115,499],"size":32,"color":"#fff","family":"serif","align":"right","vertical":false},{"text":"06","rect":[700,520,760,570],"size":45,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Documentary","rect":[815,520,1115,570],"size":32,"color":"#fff","family":"serif","align":"right","vertical":false},{"text":"07","rect":[700,596,760,646],"size":45,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Outtakes","rect":[815,596,1115,646],"size":32,"color":"#fff","family":"serif","align":"right","vertical":false},{"text":"08","rect":[700,672,760,722],"size":45,"color":"#fff","family":"serif","align":"left","vertical":false},{"text":"Afterword","rect":[815,672,1115,722],"size":32,"color":"#fff","family":"serif","align":"right","vertical":false},{"text":"In an age of information overload, photojournalism records social change and conveys the pulse of our times through its distinctive perspective and power. As journalism students, we understand its importance: it is a dialogue with people and events, and a vital channel through which reporters communicate. It demands not only sound photographic technique, but also a keen news sense and a deep concern for people.","rect":[126,138,530,293],"size":18.4,"color":"#eee","family":"sans","align":"left","vertical":false},{"text":"This semester, we entered the challenging and compelling world of Photojournalism. We began by collecting news-photography examples, then photographed lines, composition and campus life, before making portraits of strangers and practising documentary reporting. Every assignment challenged our abilities; every exercise deepened our understanding of photojournalism.","rect":[126,317,530,446],"size":18.4,"color":"#eee","family":"sans","align":"left","vertical":false},{"text":"This booklet brings together what we learned during the semester. It records our growth from tentative beginners towards greater maturity, and our passage from unfamiliarity to a love of photojournalism. Every image holds our effort; every passage shares what we noticed, felt and thought.","rect":[126,470,530,599],"size":18.4,"color":"#eee","family":"sans","align":"left","vertical":false},{"text":"Through this booklet, we hope more people will discover the appeal of photojournalism and the stories and emotions behind its images. We also hope to continue recording life with our cameras and telling stories through light and shadow, contributing in our own way to the development of photojournalism.","rect":[126,623,530,753],"size":18.4,"color":"#eee","family":"sans","align":"left","vertical":false},{"text":"Huimin Wu\n12 December 2024","rect":[450,773,551,820],"size":15,"color":"#eee","family":"sans","align":"left","vertical":false}],"transcript":{"en":["Foreword","Contents","Contents","01","News","02","Lines","03","Composition","04","Campus","05","Society","06","Documentary","07","Outtakes","08","Afterword","In an age of information overload, photojournalism records social change and conveys the pulse of our times through its distinctive perspective and power. As journalism students, we understand its importance: it is a dialogue with people and events, and a vital channel through which reporters communicate. It demands not only sound photographic technique, but also a keen news sense and a deep concern for people.","This semester, we entered the challenging and compelling world of Photojournalism. We began by collecting news-photography examples, then photographed lines, composition and campus life, before making portraits of strangers and practising documentary reporting. Every assignment challenged our abilities; every exercise deepened our understanding of photojournalism.","This booklet brings together what we learned during the semester. It records our growth from tentative beginners towards greater maturity, and our passage from unfamiliarity to a love of photojournalism. Every image holds our effort; every passage shares what we noticed, felt and thought.","Through this booklet, we hope more people will discover the appeal of photojournalism and the stories and emotions behind its images. We also hope to continue recording life with our cameras and telling stories through light and shadow, contributing in our own way to the development of photojournalism.","Huimin Wu\n12 December 2024"],"zh":["卷首语","在这个信息爆炸的时代，新闻摄影以其独特的视角和\n力量，记录着社会的变迁，传递着时代的脉动。作为\n新闻学专业的学生，我们深知新闻摄影的重要性，它\n是同人物、事件的对话，是记者传达信息重要的渠\n道，它不仅要求我们掌握扎实的摄影技术，更要求我\n们具备敏锐的新闻触觉和深厚的人文关怀。","本学期，我们踏入了《新闻摄影》这门充满挑战与魅\n力的课程。从最初的新闻摄影资讯收集，到线条、构\n图、校园人文的拍摄，再到给陌生人拍张照、新闻纪\n实摄影的实践，每一次作业都是一次对自我能力的挑\n战，每一次实践都是一次对新闻摄影的深刻理解。","这本实验册子，是我们本学期学习成果的集中展现。\n它记录了我们从青涩到成熟的成长历程，也见证了我\n们对新闻摄影从陌生到热爱的转变。在这里，每一幅\n作品都凝聚着我们的心血与汗水，每一段文字都诉说\n着我们的感悟与思考。","希望通过这本实验册子，能够让更多的人了解新闻摄\n影的魅力，感受新闻摄影背后的故事与情感。同时，\n也期待在未来的日子里，我们能够继续用镜头记录生\n活，用光影讲述故事，为新闻摄影事业的发展贡献自\n己的力量。","吴慧敏\n2024/12/12"]}},{"number":3,"title":{"en":"News photography I","zh":"新闻资讯（一）"},"width":1190.25,"height":842.25,"boxes":[{"text":"The Big Forget","rect":[697.8920288085938,277.0312805175781,800.6062622070312,298.8337707519531],"size":21.802499771118164,"color":"#070606","family":"serif","align":"left","vertical":false},{"text":"This photograph is striking both technically and narratively. A woman living with dementia sits alone, watching people come and go. The moving figures are blurred through a tracking technique, bringing her inner loneliness into focus. Perhaps the world appears similarly indistinct to her: people pass nearby, but nobody truly stays.\n\nThe photographer uses the contrast between stillness and movement to tell the story. The blurred women suggest time passing and a world continuing around her, evoking how dementia can disconnect someone from their surroundings. The older woman remains still, conveying isolation. The plain blackboard behind her adds a feeling of neglect or abandonment, suggesting how society forgets people with dementia.\n\nA slower shutter captures motion blur while keeping the seated woman sharply focused. The central composition draws attention to her, while the blurred figures bring movement. Soft natural light complements the warm ochre palette. The framing directs our gaze first to the seated woman, and the surrounding blur strengthens the sense of time passing.\n\nThe vivid clothing worn by many African people contrasts with narratives of Africa so often framed through poverty, illness, drought and war. That collision between cultural colour and harsh realities repeatedly moves me.","rect":[892.8101806640625,103.32167053222656,1153.677490234375,323.9285888671875],"size":8.668930053710938,"color":"#070606","family":"sans","align":"left","vertical":false},{"text":"Here, the doors don't know me,","rect":[910.29150390625,504.6081848144531,1139.18359375,526.41064453125],"size":21.802499771118164,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"At first glance, this seems closer to art photography than news photography: poetic writing accompanies an artistic image. Yet it contains almost every significant detail of its subject: displaced people, the canal, letter-writing and collective memory.\n\nThe figure, almost submerged, carries a faint suggestion of death, but also a quiet beauty. Sunlight refracted through the water lends the subject a sacred radiance.\n\nI am particularly drawn to this work. It is distinctive and inventive, and its post-production serves a purpose. Rather than portraying displaced people and an endangered culture only through suffering, the photographer shows their determination to preserve that culture and create personal archives of memory: a resilience that turns towards life even in the presence of death.","rect":[612.7218627929688,347.7884521484375,864.58203125,464.3681945800781],"size":8.668930053710938,"color":"#070606","family":"sans","align":"left","vertical":false},{"text":"What is the price of peace in Afghanistan? The photographer answers with images of countless civilians, including women and children, killed or injured.\n\nThe light has gone from this child’s eyes, replaced by fear, uncertainty and the emptiness of having faced death. The wound beneath the eye, the scars revealed by a lifted shirt, and the deliberately muted yellow palette create a profound sense of sorrow.\n\nThe composition is simple and the clothing plain. A yellow cast falls over what was originally white fabric, recalling the dust of war and a gloom that refuses to lift.\n\nThe war may be over, but rebuilding the country and healing psychological wounds will take far longer. War appears so often in outstanding award-winning photojournalism because its consequences are so devastating.","rect":[619,571,1145,734],"size":8.668930053710938,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"News photography","rect":[395.7213439941406,424.8448486328125,574.089111328125,472.8448486328125],"size":48.0,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"The ten photographs in this chapter are drawn from winners of the 66th World Press Photo Contest in 2023. The award has already established their news value; my readings are guided more by emotional response and aesthetic appreciation.","rect":[319.5119323730469,616.7018432617188,569.889892578125,748.0845947265625],"size":15.75,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"01","rect":[455.8883361816406,505.994873046875,513.9202880859375,553.994873046875],"size":48.0,"color":"#000000","family":"serif","align":"left","vertical":false}],"transcript":{"en":["The Big Forget","This photograph is striking both technically and narratively. A woman living with dementia sits alone, watching people come and go. The moving figures are blurred through a tracking technique, bringing her inner loneliness into focus. Perhaps the world appears similarly indistinct to her: people pass nearby, but nobody truly stays.\n\nThe photographer uses the contrast between stillness and movement to tell the story. The blurred women suggest time passing and a world continuing around her, evoking how dementia can disconnect someone from their surroundings. The older woman remains still, conveying isolation. The plain blackboard behind her adds a feeling of neglect or abandonment, suggesting how society forgets people with dementia.\n\nA slower shutter captures motion blur while keeping the seated woman sharply focused. The central composition draws attention to her, while the blurred figures bring movement. Soft natural light complements the warm ochre palette. The framing directs our gaze first to the seated woman, and the surrounding blur strengthens the sense of time passing.\n\nThe vivid clothing worn by many African people contrasts with narratives of Africa so often framed through poverty, illness, drought and war. That collision between cultural colour and harsh realities repeatedly moves me.","Here, the doors don't know me,","At first glance, this seems closer to art photography than news photography: poetic writing accompanies an artistic image. Yet it contains almost every significant detail of its subject: displaced people, the canal, letter-writing and collective memory.\n\nThe figure, almost submerged, carries a faint suggestion of death, but also a quiet beauty. Sunlight refracted through the water lends the subject a sacred radiance.\n\nI am particularly drawn to this work. It is distinctive and inventive, and its post-production serves a purpose. Rather than portraying displaced people and an endangered culture only through suffering, the photographer shows their determination to preserve that culture and create personal archives of memory: a resilience that turns towards life even in the presence of death.","What is the price of peace in Afghanistan? The photographer answers with images of countless civilians, including women and children, killed or injured.\n\nThe light has gone from this child’s eyes, replaced by fear, uncertainty and the emptiness of having faced death. The wound beneath the eye, the scars revealed by a lifted shirt, and the deliberately muted yellow palette create a profound sense of sorrow.\n\nThe composition is simple and the clothing plain. A yellow cast falls over what was originally white fabric, recalling the dust of war and a gloom that refuses to lift.\n\nThe war may be over, but rebuilding the country and healing psychological wounds will take far longer. War appears so often in outstanding award-winning photojournalism because its consequences are so devastating.","News photography","The ten photographs in this chapter are drawn from winners of the 66th World Press Photo Contest in 2023. The award has already established their news value; my readings are guided more by emotional response and aesthetic appreciation.","01"],"zh":["The Big Forget","这张照片无论是从摄影技术来说还是题材叙述来说都是出彩的，患\n有痴呆症状的妇女孤独地坐在那里，望着来来去去的人，动态的\n人，用追焦的方法达到虚化，突出了痴呆妇女内心的孤独，她眼中\n的世界可能也就是如此虚化的、模糊不清的，她身旁的人来来往\n往，但是没有人真的停留。\n摄影师巧妙地运用了静止与运动的对比来讲述故事。周围女性的动\n作模糊，暗示时间的流逝或世界的运行，这象征着痴呆症患者可能\n会与外界脱节。静坐的老年女性姿态不变，反映出一种与世界脱离\n的孤独感。背景中的简单黑板增添了一种被忽视或被遗弃的感觉，\n象征着痴呆症患者如何被社会遗忘。\n选择较慢的快门速度让摄影师能够捕捉到周围行走的女性的运动模\n糊，同时保持坐着的女性清晰对焦。这一技术选择强化了静止与运\n动的叙事对比。构图将坐着的女性置于画面中心，吸引观者的注意\n力，而周围的模糊人物则提供了动态元素。光线柔和自然，补充了\n环境中温暖的土黄色调。画面的框架确保观者的目光首先集中在坐\n着的女性身上，周围的模糊则增强了时间流逝的感觉。\n非洲人民喜穿鲜艳颜色的衣服，而表达非洲的叙事常常是贫困、疾\n病、干旱、战争等，因此这种文化与事实上的冲击也常常给我震撼\n的感觉。","Here, the doors don't know me, ","这张图片第一看上去不像是新闻摄影，更像是艺术摄影，诗意的\n文字叙述配上艺术的图像。\n但是这张图片又几乎包含了该题材的全部重大细节：被驱逐的\n人、运河、写信与集体记忆。\n几乎淹没在运河中的人，有一种淡淡的死亡感，但也有一种恬静\n的美感，而通过水面折射的阳光也给主角带上了神圣的光辉。\n我个人很喜欢这张摄影作品，它足够独特有创意，后期的处理并\n不多余。其次，对于被驱逐的人和被危及的文化，摄影师不是用\n苦难叙述，而是展示了一种保存自己文化，建立私人记忆档案的\n顽强与向死而生的韧劲。","阿富汗和平的代价是什么呢？摄影师用图片告诉我们了——是无\n数的平民甚至儿童妇女的死亡与受伤。\n这个儿童的眼中失去了光芒，取而代之的是恐惧、迷茫与经历过\n生死之后的空洞，眼下的伤与撩起衣服展示的伤疤，配上摄影师\n特意展示的暗黄色的色调，有种无限的悲伤与沉痛之感。\n画面简单，主人公穿着更是朴素。本来是洁白的衣服，作者暗黄\n色的滤镜与灯光笼罩在人物之上，让我们联想到战争的尘土，像\n是挥之不去的阴霾。\n战争虽然结束了，但战后重建和战后人民心里创伤的愈合，任重\n道远。\n战争，是获奖的优秀新闻中常见的主题，实在是因为，战争带来\n的结果太过惨痛。\nThe Price of Peace in Afghanistan","新闻资讯","本篇章十张图片均选自2023年第66\n届世界新闻摄影大赛（荷赛）获奖\n作品。这个奖项已经帮我检验了这\n些图片的新闻价值，我选择解读他\n们，更多是从感性的角度和审美的\n欣赏选择的。","01"]}},{"number":4,"title":{"en":"News photography II","zh":"新闻资讯（二）"},"width":1190.25,"height":842.25,"boxes":[{"text":"The Price of Peace in Afghanistan","rect":[48.04862594604492,220.12428283691406,289.9671630859375,241.92678833007812],"size":21.802499771118164,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"This powerful photograph uses a familiar photojournalistic device: contrast. The warm yellow light on the right opposes the dark, cold surroundings on the left. Food inside the room contrasts with hungry people who cannot afford it. A kneeling figure gazes longingly at the food, while a customer stands buying it; a crowd of hungry people faces a single paying customer.\n\nContrast endures because it communicates a story with emotional force. Through colour, light and symmetrical composition, the photographer emphasises the tragic circumstances of Afghanistan’s people.","rect":[42.979652404785156,250.5632781982422,294.83984375,355.58447265625],"size":8.668930053710938,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Three women lean at different heights over the only spring. They are soaked, but at least they have water to drink.\n\nThe lowest lies on her side, looking into the distance as though she has drunk her fill and is thinking. The second also looks away, in another direction. At the top, a woman kneels and cups the water to drink. They seem to have climbed up in turn to reach the cleanest water, then paused, already worrying about what comes next. Dry land stretches around them; nobody knows when they will next drink enough.\n\nReflections on the water suggest fierce sunlight. Apart from this single spring, the ground is parched. Water scarcity weighs heavily on local lives.\n\nThe raised spring and the women’s different levels give the image depth and a sense of time and place. I find this contrast—something available, but only just—more telling than an uninterrupted expanse of drought.","rect":[318.3154602050781,259.2320556640625,570.1756591796875,387.370361328125],"size":8.668930053710938,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"In this intensely affecting scene, the photographer focuses on an injured civilian being rescued, communicating a strong humanitarian concern.\n\nCapturing this instant creates immediacy and documentary force. The rescuers’ expressions and movements, set against the ruined background, convey the tension and chaos of disaster. Muted surroundings contrast sharply with the red stretcher fabric, concentrating attention. The rescuers and injured person occupy the centre, with rubble giving essential context. Natural light and strongly contrasting tones make the photograph heavy with tension.","rect":[318.3154602050781,613.3604736328125,570.6173095703125,718.758056640625],"size":8.699999809265137,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"The Siege of Mariupol","rect":[369.653564453125,577.111328125,524.2036743164062,598.913818359375],"size":21.802499771118164,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Battered Waters","rect":[389.65576171875,220.12428283691406,501.6127014160156,241.92678833007812],"size":21.802499771118164,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"The Price of Peace in Afghanistan","rect":[52.786460876464844,534.55029296875,290.20465087890625,555.9472045898438],"size":21.396915435791016,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Through an image of people in the Peruvian Andes, this work explores their close relationship with the natural environment. The person holding an alpaca represents a livelihood dependent on land and animals. More than a portrait, it conveys coexistence and the herders’ reliance on, and protection of, their environment.\n\nThe composition is dramatic. The farmer and alpaca stand high in the centre, against mountains and an expansive sky, appearing both solitary and strong. Muted colours give the image solemnity and calm. Cinque uses natural light and shadow to emphasise the vast landscape and the person’s presence, suggesting resilience before nature.\n\nCinque uses a telephoto or wide-angle lens with considerable depth of field to retain detail in both the subject and distant mountains. Strong light–shadow contrasts define the farmer and alpaca while making the landscape more majestic. A slightly low viewpoint strengthens the subject’s presence, as though she were looking over the land that sustains her.","rect":[45.33063507080078,573.8052368164062,296.0382995605469,745.54736328125],"size":8.538155555725098,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Ferrero’s image conveys Venezuela’s political turmoil and the tense relationship between police and the public. The restrained man embodies powerlessness and suppression, while the collective presence of riot police represents the coercive power of the state. This contrast exposes unequal power and communicates violence, fear and helplessness. A small-scale encounter points towards larger questions of political repression and social unrest, inviting viewers to consider Venezuela’s wider predicament.\n\nThe low viewpoint brings us emotionally close to the person on the ground, as though we too were surrounded. The ground and the person’s head occupy the bottom of the frame, making the police loom more oppressively. Heavy, neutral greys intensify the tension. With few extraneous elements, the composition directs attention to the relationship between the individual and the police.\n\nA fast shutter clearly captures the action: armour, shields and the restrained person’s expression remain visible. Natural light recreates the tension of the street without conspicuous effects. The photograph suggests the quick reactions and timing required to work amid upheaval.","rect":[877.995361328125,246.92884826660156,1140.519775390625,468.3263854980469],"size":8.699999809265137,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"I Can't Hear the Birds","rect":[940.8601684570312,221.83322143554688,1078.3360595703125,243.8307342529297],"size":21.997499465942383,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Australian Floods in Infrared","rect":[645.763671875,322.5228271484375,824.4823608398438,344.52032470703125],"size":21.997499465942383,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Aerial infrared photography renders vegetation pink and red against the blue and cyan of water. These complementary colours make the scene dreamlike, almost a fairy tale, despite its severe subject: flooding and the climate crisis.\n\nThe images also have practical value. They help emergency responders identify newly flooded areas and support subsequent rescue and recovery work.","rect":[603.52392578125,358.1588439941406,864.5258178710938,428.7564392089844],"size":8.699999809265137,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Shifting","rect":[709.23291015625,663.3495483398438,755.4252319335938,685.3470458984375],"size":21.997499465942383,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Open-format work expands the expressive possibilities of photojournalism. Imaginative post-production need not conflict with truth and objectivity when it appropriately conveys a person’s psychology and story. An artistic, film-strip-like composite can also be excellent journalism.\n\nTo me, this work’s distinctive feature is not the film-strip format, but the large areas of black and near-black imagery. As the introduction explains, these are Valentina’s imaginings of life and experiences with her imprisoned mother. A child’s imagination can be rich, strange and innocent, yet full of gaps. Those blank spaces make the work feel truthful and leave room for our own imagination.\n\nAlthough Valentina’s mother was imprisoned because of drug use, the child’s love for her remains beautiful.","rect":[877.995361328125,510.0755920410156,1140.0760498046875,650.273193359375],"size":8.699999809265137,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Reflection: Looking at these accomplished works, I marvel not only at the events and photographic technique, but also at the imagination and creativity. Photojournalism need not be confined to a single form; what it communicates—its content and ideas—matters most.","rect":[609.1527099609375,714.5155029296875,1135.6953125,796.3015747070312],"size":19.524105072021484,"color":"#004aad","family":"sans","align":"left","vertical":false}],"transcript":{"en":["The Price of Peace in Afghanistan","This powerful photograph uses a familiar photojournalistic device: contrast. The warm yellow light on the right opposes the dark, cold surroundings on the left. Food inside the room contrasts with hungry people who cannot afford it. A kneeling figure gazes longingly at the food, while a customer stands buying it; a crowd of hungry people faces a single paying customer.\n\nContrast endures because it communicates a story with emotional force. Through colour, light and symmetrical composition, the photographer emphasises the tragic circumstances of Afghanistan’s people.","Three women lean at different heights over the only spring. They are soaked, but at least they have water to drink.\n\nThe lowest lies on her side, looking into the distance as though she has drunk her fill and is thinking. The second also looks away, in another direction. At the top, a woman kneels and cups the water to drink. They seem to have climbed up in turn to reach the cleanest water, then paused, already worrying about what comes next. Dry land stretches around them; nobody knows when they will next drink enough.\n\nReflections on the water suggest fierce sunlight. Apart from this single spring, the ground is parched. Water scarcity weighs heavily on local lives.\n\nThe raised spring and the women’s different levels give the image depth and a sense of time and place. I find this contrast—something available, but only just—more telling than an uninterrupted expanse of drought.","In this intensely affecting scene, the photographer focuses on an injured civilian being rescued, communicating a strong humanitarian concern.\n\nCapturing this instant creates immediacy and documentary force. The rescuers’ expressions and movements, set against the ruined background, convey the tension and chaos of disaster. Muted surroundings contrast sharply with the red stretcher fabric, concentrating attention. The rescuers and injured person occupy the centre, with rubble giving essential context. Natural light and strongly contrasting tones make the photograph heavy with tension.","The Siege of Mariupol","Battered Waters","The Price of Peace in Afghanistan","Through an image of people in the Peruvian Andes, this work explores their close relationship with the natural environment. The person holding an alpaca represents a livelihood dependent on land and animals. More than a portrait, it conveys coexistence and the herders’ reliance on, and protection of, their environment.\n\nThe composition is dramatic. The farmer and alpaca stand high in the centre, against mountains and an expansive sky, appearing both solitary and strong. Muted colours give the image solemnity and calm. Cinque uses natural light and shadow to emphasise the vast landscape and the person’s presence, suggesting resilience before nature.\n\nCinque uses a telephoto or wide-angle lens with considerable depth of field to retain detail in both the subject and distant mountains. Strong light–shadow contrasts define the farmer and alpaca while making the landscape more majestic. A slightly low viewpoint strengthens the subject’s presence, as though she were looking over the land that sustains her.","Ferrero’s image conveys Venezuela’s political turmoil and the tense relationship between police and the public. The restrained man embodies powerlessness and suppression, while the collective presence of riot police represents the coercive power of the state. This contrast exposes unequal power and communicates violence, fear and helplessness. A small-scale encounter points towards larger questions of political repression and social unrest, inviting viewers to consider Venezuela’s wider predicament.\n\nThe low viewpoint brings us emotionally close to the person on the ground, as though we too were surrounded. The ground and the person’s head occupy the bottom of the frame, making the police loom more oppressively. Heavy, neutral greys intensify the tension. With few extraneous elements, the composition directs attention to the relationship between the individual and the police.\n\nA fast shutter clearly captures the action: armour, shields and the restrained person’s expression remain visible. Natural light recreates the tension of the street without conspicuous effects. The photograph suggests the quick reactions and timing required to work amid upheaval.","I Can't Hear the Birds","Australian Floods in Infrared","Aerial infrared photography renders vegetation pink and red against the blue and cyan of water. These complementary colours make the scene dreamlike, almost a fairy tale, despite its severe subject: flooding and the climate crisis.\n\nThe images also have practical value. They help emergency responders identify newly flooded areas and support subsequent rescue and recovery work.","Shifting","Open-format work expands the expressive possibilities of photojournalism. Imaginative post-production need not conflict with truth and objectivity when it appropriately conveys a person’s psychology and story. An artistic, film-strip-like composite can also be excellent journalism.\n\nTo me, this work’s distinctive feature is not the film-strip format, but the large areas of black and near-black imagery. As the introduction explains, these are Valentina’s imaginings of life and experiences with her imprisoned mother. A child’s imagination can be rich, strange and innocent, yet full of gaps. Those blank spaces make the work feel truthful and leave room for our own imagination.\n\nAlthough Valentina’s mother was imprisoned because of drug use, the child’s love for her remains beautiful.","Reflection: Looking at these accomplished works, I marvel not only at the events and photographic technique, but also at the imagination and creativity. Photojournalism need not be confined to a single form; what it communicates—its content and ideas—matters most."],"zh":["The Price of Peace in Afghanistan","这张照片非常具有震撼力，运用了新闻摄影中常见的叙述手段\n——对比。\n右边暖黄色的灯光与左边昏暗阴冷的环境对比，右边房中的粮食\n与左边饥肠辘辘但没钱购买粮食的人民的对比，跪坐着渴望地望\n着房中粮食地人与站着购买的顾客对比，人数众多的饥饿者与唯\n一一个顾客的对比。\n对比之所以经久不衰，是因为对比可以更好地表达与叙述，更有\n震撼人心的效果。这位摄影师巧妙利用色调、光线、对称构图，\n来突出阿富汗人民的悲惨命运。","唯一的泉水之上，高高低低地趴着三个妇女，她们浑身湿透了，\n但是至少她们有水喝了。\n最底下的妇女侧躺着，望向远方，好像是已经喝饱了水在深思；\n第二个妇女也望向远方，但是另一个方向；最上面的妇女跪坐着\n捧起喷泉水，准备喝。它们三个像是依次爬到最顶上去享受最干\n净的水，喝完之后小憩，但同时为以后的水感到焦虑，举目望去\n皆是干旱的土地，下一次享受喝足的感觉，已不知是什么时候。\n从水面的反光来看，我们知道这是烈日之下，而画面内出了一处\n泉，皆是干涸的土，缺水的问题严重困扰当地的人。\n有高度的泉和高低错落的人给画面增加了立体感，也有了时空\n感。比起一望无际的干旱，我更喜欢这种有但仅有的对比。","这幅作品通过一张极具冲击力的场景摄影师将焦点放在受伤的平民\n及其被救援的过程中，传递出强烈的人道主义关怀。\n摄影师通过抓拍这一刻，展现了极强的现场感和纪实性。照片中救\n援人员的面部表情、动作、以及背景中的废墟，形成了鲜明的对\n比，突显了灾难中的紧张与混乱。颜色的处理上，暗淡的背景和鲜\n红的担架布形成强烈的视觉冲击，使得画面中的焦点更加突出。构\n图方面，救援人员和受伤者处于画面的中央，视线自然聚焦于此，\n背景的废墟提供了强有力的环境衬托。这张照片通过使用自然光和\n对比鲜明的色调，使整个画面显得沉重且富有张力。","The Siege of Mariupol","Battered Waters","The Price of Peace in Afghanistan","作品通过捕捉秘鲁安第斯山脉居民的形象，探讨了他们与自然环境\n的紧密联系。画面中的人物抱着羊驼，象征着他们的生计依赖于这\n片土地和动物。这不仅是一幅肖像照，更传递了人与自然共生的关\n系，体现了牧民们对自然环境的依赖与保护。\n这张照片在构图上极具戏剧性。画面中央的农民和羊驼位于高地，\n背景是雄伟的山脉和辽阔的天空，使得人物显得既孤独又充满力\n量。色彩的选择偏向于暗淡的色调，使得整个画面充满了庄严感与\n宁静的氛围。Cinque 巧妙地利用了自然光和阴影，增强了环境的广\n阔感和人物的存在感，暗示着他们在自然面前的坚韧与韧性。\nCinque 运用了长焦镜头或广角镜头，以较大的景深捕捉了远处的山\n脉和人物的细节，确保画面中所有元素都清晰可见。照片的光线处\n理令人印象深刻，强烈的光影对比突出了农民和羊驼的轮廓，同时\n使背景的自然景观看起来更加宏伟。Cinque 选择了一个略低的拍摄\n角度，这一角度增强了人物的存在感，仿佛她在俯瞰着她赖以为生\n的土地。","Ferrero 通过这幅图像展现了委内瑞拉动荡的政治局势和警民冲突的\n紧张关系。图中的男子处于被制服的状态，象征了无力感和被压制的\n个体，而防暴警察的集体形象则代表了国家机器的强权与压迫。这种\n对比展现了权力的不对等，并传达了暴力、恐惧以及无助的社会现\n实。Ferrero 通过这种微观视角，揭示了更为宏观的社会问题，如政\n治镇压和社会动荡，让观众不仅仅看到眼前的场景，更能够联想到委\n内瑞拉的整体困境。\n摄影师采用了低角度的视角，使得观众与地上的被压制者产生了情感\n共鸣，仿佛我们也处于这个被围困的环境中。地面和人的头部处于画\n面底部，使得警察的高大形象显得更加压迫感十足。色调上，Ferrero\n选择了中性而沉重的灰色，进一步强化了画面中的紧张感和压迫感。\n画面中没有多余的元素，简洁的构图让观众的注意力集中在人物和防\n暴警察的关系上，增强了叙事性。\nFerrero 运用了较快的快门速度，清晰捕捉了动态场景中的每一个细\n节。警察的护甲、盾牌和被压制者的表情都清晰可见，展现了摄影师\n对动作和细节的把控力。光线的运用非常自然，虽然没有特别的光影\n效果，但真实再现了街头的紧张场景，让画面充满了纪实感。摄影师\n显然是在高度紧张和动荡的环境中拍摄，体现了她在混乱中的快速反\n应和抓拍能力。","I Can't Hear the Birds","Australian Floods in Infrared","摄影师使用空中红外成像，将植被呈现为粉红色和红色，与代表水的\n蓝色和青色形成鲜明对比。粉红色与青色的相得益彰，使得图片具有\n梦幻的色彩，像是童话世界的场景。但实际表达的确实洪水与气候危\n机这种冷峻的题材，对比明显。\n摄影师拍摄的图片还具有现实意义，这些图像使灾后紧急救援人员，\n可以轻松识别新的洪水区域，从而协助后续救援和恢复工作。","Shifting","这类开放格式的作品增加了新闻摄影的表现形式，可以通过后期加\n工，带有想象力地展开，而这并不违背新闻本身要求的真实与客观，\n如果能恰如其分地表现人物的心理与故事的面貌，这类胶卷样式的艺\n术合成照片也是优秀的新闻作品。\n我认为这幅作品独特之处并不是胶卷式的表达，而是大量的黑色画面\n以及接近黑色的昏暗画面。\n正如作品简介所说，这是Valentina的想象，是一个孩子对与已经入狱\n的母亲一起生活和经历的想象，孩童的想象是丰富的，怪诞的，天真\n的，但也有很多空白。因此大量的留白表达既显示出作品的真实性，\n也给我们留下很多想象的余地。\n尽管Valentina的母亲因为吸毒而入狱，但一个孩子对母亲的爱仍旧是\n美好的。","实验心得：观看大师之作，除了对事件本身、新闻摄影技术\n的感叹，更多的是对想象力和创造力和惊叹。原来新闻摄影\n并不拘泥于形式，传达的内容和思想本身更具有意义。"]}},{"number":5,"title":{"en":"Lines—Paths through Life","zh":"线条——人生轨"},"width":1190.25,"height":842.25,"boxes":[{"text":"Lines—Paths through Life","rect":[246.500732421875,564.173583984375,532.8203125,612.173583984375],"size":48.0,"color":"#ffffff","family":"serif","align":"left","vertical":false},{"text":"02","rect":[364.7795104980469,621.3236083984375,427.1314392089844,669.3236083984375],"size":48.0,"color":"#ffffff","family":"serif","align":"left","vertical":false},{"text":"Initial thoughts: As soon as we received the theme “lines”, I began observing my surroundings: fallen strands of hair tangled together, patches of rust on my dormitory door and wall, and the boundaries between light and shadow…","rect":[964.5467529296875,16.05385971069336,1131.1768798828125,216.6851806640625],"size":17.89543342590332,"color":"#0097b2","family":"sans","align":"left","vertical":false},{"text":"Reflection: Lines were the starting point of our photographic practice. Beginning with this simple element, our teacher showed how details and wider views produce different effects. I found that ordinary things can become surprising when viewed from a different angle or photographed close up. Under the theme “Paths through Life”, I explored decay, falling and shadow as forms that recur across different things, using them as metaphors for states of life.","rect":[652.433837890625,680.1929321289062,1132.31787109375,794.0046997070312],"size":16.519651412963867,"color":"#004aad","family":"sans","align":"left","vertical":false},{"text":"Work in progress: After photographing familiar sights, I found that natural forms came closest to what I wanted to express. I had planned to show a tangle of cables, but arranging them by hand produced only stiffness.","rect":[651.1610107421875,227.95838928222656,809.635009765625,442.50726318359375],"size":17.019485473632812,"color":"#0097b2","family":"sans","align":"left","vertical":false},{"text":"Later adjustments: The camera does not show exactly what the eye sees. By adjusting saturation and contrast in post-production, I made the visual intention clearer.","rect":[964.5467529296875,469.6146240234375,1129.7762451171875,619.0593872070312],"size":17.744998931884766,"color":"#0097b2","family":"sans","align":"left","vertical":false}],"transcript":{"en":["Lines—Paths through Life","02","Initial thoughts: As soon as we received the theme “lines”, I began observing my surroundings: fallen strands of hair tangled together, patches of rust on my dormitory door and wall, and the boundaries between light and shadow…","Reflection: Lines were the starting point of our photographic practice. Beginning with this simple element, our teacher showed how details and wider views produce different effects. I found that ordinary things can become surprising when viewed from a different angle or photographed close up. Under the theme “Paths through Life”, I explored decay, falling and shadow as forms that recur across different things, using them as metaphors for states of life.","Work in progress: After photographing familiar sights, I found that natural forms came closest to what I wanted to express. I had planned to show a tangle of cables, but arranging them by hand produced only stiffness.","Later adjustments: The camera does not show exactly what the eye sees. By adjusting saturation and contrast in post-production, I made the visual intention clearer."],"zh":["线条——人生轨","02","前期思考：在拿到线\n条这个题目的时候，\n我马上就观察了生活\n的四周，我掉落的头\n发缠绕在一起、寝室\n门墙上斑驳的锈迹、\n光投下而形成的明暗\n对比……","实验心得：线条是我们课程拍摄的起点，从最简单的线条开始，\n老师教我们局部与整体拍摄展现出来的不同效果，在实践探索过\n程中，我发现稀松平常的东西换个角度，放大去拍摄，会有出其\n不意的效果。我以人生轨作为主体，展示了朽、落、影等出现在\n我们生命中不同事物的形态，比喻我们人生的状态。","中期成果：当我向熟\n悉的景物按下快门\n后，我发现越是自然\n的形态越能够展现我\n想要的样子，因为我\n本想展示各种数据线\n缠绕在一起的样子，\n但人为的缠绕只留下\n僵硬的感觉。","后期调整：相机展现\n的样子与肉眼看到的\n样子有点区别，我通\n过饱和度、对比度等\n后期调整，将画面变\n得更加明确。"]}},{"number":6,"title":{"en":"Composition I","zh":"构图（一）"},"width":1190.25,"height":842.25,"boxes":[{"text":"Composition","rect":[868,4,995,47],"size":34,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"Reflections","rect":[1167,169,1190,360],"size":19,"color":"#111111","family":"sans","align":"left","vertical":true},{"text":"On rainy days, the world becomes a vast mirror.","rect":[1134,170,1158,495],"size":19,"color":"#111111","family":"sans","align":"left","vertical":true},{"text":"Composition","rect":[141,378,310,428],"size":40,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"03","rect":[154,450,220,499],"size":48,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"Diagonal composition","rect":[470,90,587,111],"size":15,"color":"#111","family":"sans","align":"left","vertical":false},{"text":"Initial thoughts\nBefore this exercise, I studied the principles behind classical compositional approaches: reflections, the golden ratio, central composition, diagonals, foregrounds, triangles and curves. Each guides the viewer’s eye differently, strengthening an image’s expression and storytelling.","rect":[203,715,596,839],"size":15,"color":"#555","family":"sans","align":"left","vertical":false},{"text":"Work in progress: Going out in the rain, I was drawn to light reflected on water—a natural mirror. I especially enjoy reflection-based compositions because their blurred forms leave room for imagination. Wandering through campus, I changed my position and angle to explore different compositions.","rect":[638,635,1044,760],"size":17.7,"color":"#555","family":"sans","align":"left","vertical":false}],"transcript":{"en":["Composition","Reflections","On rainy days, the world becomes a vast mirror.","Composition","03","Diagonal composition","Initial thoughts\nBefore this exercise, I studied the principles behind classical compositional approaches: reflections, the golden ratio, central composition, diagonals, foregrounds, triangles and curves. Each guides the viewer’s eye differently, strengthening an image’s expression and storytelling.","Work in progress: Going out in the rain, I was drawn to light reflected on water—a natural mirror. I especially enjoy reflection-based compositions because their blurred forms leave room for imagination. Wandering through campus, I changed my position and angle to explore different compositions."],"zh":["构图","倒\n影\n构\n图","雨\n天\n，\n世\n界\n变\n成\n一\n面\n巨\n大\n的\n镜\n子\n构图","03","对角线构图","前期思考\n在进行本次构图实验之前，我首先深入研究了各种经典构图\n法则的理论基础，包括倒影构图、黄金分割线构图、居中构\n图、对角线构图、前景构图、三角形构图以及曲线构图。这\n些构图方法各有特色，能够引导观众的视线，增强照片的表\n现力和故事性。","中期成果：当我在雨天出门的时候，我就被水面光\n的反射所吸引，我想这就是一面天然的镜子。我个\n人也非常喜欢倒影构图，因为倒影的样子是模糊\n的，有很多的想象和构思空间。我在校园里漫无目\n的的逛，通过变换方位和角度来实现各种构图。"]}},{"number":7,"title":{"en":"Composition II","zh":"构图（二）"},"width":1190.25,"height":842.25,"boxes":[{"text":"1:1.618\nAn ideal proportion\nThe frame divided in two\nBeauty in its very existence","rect":[205,243,300,325],"size":16,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"Golden-ratio composition","rect":[70,23,400,59],"size":28,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"Central composition","rect":[835,42,1120,77],"size":28,"color":"#111","family":"serif","align":"left","vertical":false},{"text":"Curved composition","rect":[970,465,1130,488],"size":17,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"Triangular composition","rect":[967,688,1135,711],"size":17,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"Foreground","rect":[547,511,578,675],"size":25,"color":"#111111","family":"sans","align":"left","vertical":true},{"text":"Reflection: This exercise deepened my understanding of composition’s importance. Different approaches give photographs different emotions and atmospheres, making composition a vital means of expressing creativity and stories. In practice, I learned to adapt my choices to the setting and refine them through post-production. Above all, the exercise awakened a love of photographic art and a desire to explore. Photography is not simply recording: it is also a process of creating beauty.","rect":[668,362,858,780],"size":18,"color":"#004aad","family":"sans","align":"left","vertical":false},{"text":"Half-hidden, as behind a pipa:\nthis is the charm of a foreground.\nWith something partly in the way,\nthe subject gains a quiet beauty.","rect":[70,327,275,410],"size":15,"color":"#111111","family":"sans","align":"left","vertical":false}],"transcript":{"en":["1:1.618\nAn ideal proportion\nThe frame divided in two\nBeauty in its very existence","Golden-ratio composition","Central composition","Curved composition","Triangular composition","Foreground","Reflection: This exercise deepened my understanding of composition’s importance. Different approaches give photographs different emotions and atmospheres, making composition a vital means of expressing creativity and stories. In practice, I learned to adapt my choices to the setting and refine them through post-production. Above all, the exercise awakened a love of photographic art and a desire to explore. Photography is not simply recording: it is also a process of creating beauty.","Half-hidden, as behind a pipa:\nthis is the charm of a foreground.\nWith something partly in the way,\nthe subject gains a quiet beauty."],"zh":["1：1.618\n最佳的比例\n画面被一分为二\n存在即优美","黄金分割线构图\n居中构图","曲线构图","三角构图","前\n景\n构\n图","实验心得：通过这次构图实验，我深刻体会到构图对于摄影作品的重要性。不同的构图方法能够赋予照片不同的情感和氛围，是摄影师表达创意和故事的重要手段。在实际操作中，我学会了如何根据现场环境灵活调整构图策略，以及如何通过后期处理进一步优化构图效果。更重要的是，这次实验激发了我对摄影艺术的无限热爱和探索欲望，让我意识到摄影不仅仅是记录，更是一种创造美的过程。","犹抱琵琶半遮面\n这就是前景构图的魅力\n有了前景的遮挡\n后面的对象便有了含蓄的美"]}},{"number":8,"title":{"en":"Campus life I","zh":"校园人文（一）"},"width":1190.25,"height":842.25,"boxes":[{"text":"Traditional Culture Festival","rect":[637.7177124023438,40.763999938964844,775.0288696289062,72.75899505615234],"size":31.994998931884766,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Zhejiang University offers countless compelling moments of campus life, from students’ daily movements to distinctive events. On 30 November, the Culture Square hosted both a Traditional Culture Festival and a visiting blood-donation vehicle. Crowds filled the space.\n\nIt was the weekend, and many children joined the activities organised by traditional-culture societies: Hanfu dress, archery, calligraphy, painting and crafts…","rect":[635.65869140625,619.9688720703125,970.1035766601562,751.8832397460938],"size":15.997499465942383,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Campus Life","rect":[352.0921630859375,107.65974426269531,530.555908203125,155.6597442626953],"size":48.0,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"04","rect":[410.1497497558594,169.93324279785156,472.5016784667969,217.93324279785156],"size":48.0,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Aim\nTo observe and record the rich variety of cultural and community activities on Zhejiang University’s campus.\n\nTime and place\n30 November 2023 (weekend). Culture Square, Zhejiang University, and the surrounding area.\n\nEquipment\nCamera: to capture visual moments at the events.\nPhone: to record sounds, including performance music, children’s laughter, and conversations among donors.\nCommunication devices: for immediate updates and coordination with other team members.\n\nPreparation","rect":[32.782466888427734,327.4442443847656,532.310302734375,581],"size":15.997499465942383,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"• Define the aims and observation points, including the festival activity areas and the blood-donation vehicle.\n• As a reporter for Zhejiang University’s student reporting team, learn the event schedule.\n• Prepare interview questions for society members, donors and volunteers.","rect":[59.981685638427734,588.4442138671875,532.3102416992188,698.4326171875],"size":15.997499465942383,"color":"#000000","family":"sans","align":"left","vertical":false}],"transcript":{"en":["Traditional Culture Festival","Zhejiang University offers countless compelling moments of campus life, from students’ daily movements to distinctive events. On 30 November, the Culture Square hosted both a Traditional Culture Festival and a visiting blood-donation vehicle. Crowds filled the space.\n\nIt was the weekend, and many children joined the activities organised by traditional-culture societies: Hanfu dress, archery, calligraphy, painting and crafts…","Campus Life","04","Aim\nTo observe and record the rich variety of cultural and community activities on Zhejiang University’s campus.\n\nTime and place\n30 November 2023 (weekend). Culture Square, Zhejiang University, and the surrounding area.\n\nEquipment\nCamera: to capture visual moments at the events.\nPhone: to record sounds, including performance music, children’s laughter, and conversations among donors.\nCommunication devices: for immediate updates and coordination with other team members.\n\nPreparation","• Define the aims and observation points, including the festival activity areas and the blood-donation vehicle.\n• As a reporter for Zhejiang University’s student reporting team, learn the event schedule.\n• Prepare interview questions for society members, donors and volunteers."],"zh":["传统文化节","浙江大学校园内有无数精彩的人文瞬间，不管是学\n生们日常的穿梭还是校内外的独特的活动。\n11月30日这一天，浙江大学文化广场同时有传统文\n化节和献血车进校园的活动，人影攒动。\n正值周末，许多小朋友也参与到传统文化社团举办\n的各种活动当中，汉服、弓箭、书画、手工……","校园人文","04","实验目的：\n本实验旨在通过实地观察与记录，捕捉并展现浙江大学校园内丰富多彩的\n人文活动\n实验时间与地点：\n时间：2023年11月30日（周末）\n地点：浙江大学文化广场及周边区域\n实验材料：\n相机：用于捕捉活动现场的视觉瞬间\n手机：记录现场声音，如传统文化表演的音乐、孩子们的笑声、献血者的\n交谈等\n通讯设备：用于即时信息传递和与其他团队成员协调\n前期准备：","确定实验目标与具体观察点，包括传统文化节的活动区域和献血车位\n置。\n作为浙江大学融媒体中心学生记者团的记者，了解活动安排。\n准备采访提纲，针对传统文化社团成员提问、现场提问献血者及志愿\n者。"]}},{"number":9,"title":{"en":"Campus life II","zh":"校园人文（二）"},"width":1190.25,"height":842.25,"boxes":[{"text":"Blood Donation on Campus","rect":[71.17234802246094,42.278526306152344,235.6444549560547,74.27352142333984],"size":31.994998931884766,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Inside the donation vehicle, people wait their turn or rest after donating. Each hopes their action will give an unknown person a better chance of life.","rect":[365.06158447265625,282.4767150878906,517.5365600585938,392.6410827636719],"size":15.997499465942383,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Campus Reporting","rect":[657.8308715820312,48.19322967529297,768.0131225585938,80.18822479248047],"size":31.994998931884766,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Quietly documenting and reporting campus events are the student reporters of Zhejiang University’s integrated media centre. With cameras in hand, they record its sights, sounds and images.","rect":[798.7150268554688,13.317169189453125,1102.8316650390625,79.9815444946289],"size":15.997499465942383,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Technical adjustments","rect":[365.06158447265625,444.4811096191406,449.6153564453125,476.3334655761719],"size":21.997499465942383,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Indoors: Lower, more directional light calls for a higher ISO, wider aperture or additional lighting, such as a flash or reflector, to keep images bright and clear. Adjust white balance to avoid colour distortion. Light entering through a window or doorway can also guide the eye and build depth.\n\nOutdoors: Light is more abundant and changeable. Strong, directional sunlight suits clear outlines and vivid colours; overcast skies and dusk offer soft, diffuse light and a warm, dreamlike mood. Choose shutter speed, aperture and ISO for the conditions to avoid over- or underexposure.","rect":[365.06158447265625,475.44110107421875,1108.938720703125,607.35546875],"size":15.997499465942383,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Reflection: Photographing campus life marked a move from controlling individual elements to considering the image as a whole. A human-centred theme requires attention to storytelling and subjects’ privacy, just as photojournalism does. Combining the framing learned through lines with the viewpoints explored through composition, this exercise focused on people, events and what lies behind them.","rect":[365.06158447265625,660.368896484375,1105.0733642578125,769.8322143554688],"size":19.807498931884766,"color":"#004aad","family":"sans","align":"left","vertical":false}],"transcript":{"en":["Blood Donation on Campus","Inside the donation vehicle, people wait their turn or rest after donating. Each hopes their action will give an unknown person a better chance of life.","Campus Reporting","Quietly documenting and reporting campus events are the student reporters of Zhejiang University’s integrated media centre. With cameras in hand, they record its sights, sounds and images.","Technical adjustments","Indoors: Lower, more directional light calls for a higher ISO, wider aperture or additional lighting, such as a flash or reflector, to keep images bright and clear. Adjust white balance to avoid colour distortion. Light entering through a window or doorway can also guide the eye and build depth.\n\nOutdoors: Light is more abundant and changeable. Strong, directional sunlight suits clear outlines and vivid colours; overcast skies and dusk offer soft, diffuse light and a warm, dreamlike mood. Choose shutter speed, aperture and ISO for the conditions to avoid over- or underexposure.","Reflection: Photographing campus life marked a move from controlling individual elements to considering the image as a whole. A human-centred theme requires attention to storytelling and subjects’ privacy, just as photojournalism does. Combining the framing learned through lines with the viewpoints explored through composition, this exercise focused on people, events and what lies behind them."],"zh":["献血车进校园","在献血车上也有许多排\n队等候献血的人和献完\n血在休息的人，都希望\n自己的行为可以给陌生\n的TA更多生的机会。","校园采访","而默默记录一切，报道一切校内活动的人，就\n是浙江大学融媒体中心学生记者团的记者们，\n他们用手中的相机，记录下声色影像。","技术调整","室内：室内拍摄时，由于光线较弱且方向单一，需要使用较高的ISO值、较大的光圈或额外的光源（如闪光灯、\n反光板）来确保画面明亮且清晰。同时，注意白平衡的调整，以避免色彩失真。构图时，可以利用窗户或门缝透\n入的自然光作为引导线，增强画面的层次感。\n室外：室外拍摄时，光线更加充足且多变，可以充分利用自然光进行创作。晴天时，光线强烈且方向明确，适合\n拍摄轮廓分明、色彩鲜艳的画面；阴天或黄昏时，光线柔和且漫射，能够营造出温馨、梦幻的氛围。注意根据光\n线条件选择合适的快门速度、光圈和ISO值，以避免过曝或欠曝。","实验心得：校园人文的主题拍摄，是从对摄影单一要素把握到摄影整体把控的一次\n跨越，因为强调人文，那要考虑故事性、被拍摄对象的隐私等等，这与新闻摄影拍\n摄注意事项是一致的。将拍摄线条是对画幅的把控和拍摄构图时对角度的把控相结\n合，本次校园人文的拍摄更多聚焦于人物、事件以及二者背后的事物。"]}},{"number":10,"title":{"en":"Photographing strangers","zh":"给陌生人拍张照"},"width":1190.25,"height":842.25,"boxes":[{"text":"At the annual temple fair, countless traders gather, eating and sleeping on site over ten days, from 23 November to 3 December. It is a carnival for small-goods sellers, and the liveliest place in my childhood memories.\n\nFor children, it is paradise: rows of ring-toss prizes, balloon-shooting stalls, fishing games and inflatable playgrounds. When play becomes tiring, there is sweet candyfloss, refreshing ice cream, candied hawthorn or fragrant Xinjiang barbecue.\n\nThe fair sells almost everything for daily life: pots and bowls, shoes and clothing, potted plants and household hardware…\n\nAlongside the stalls I remember, this year brought more “beauty stalls”: mole removal, eyebrow tattooing and wigs. Men and women, young and old, were happy to visit anything that promised to make them look better.","rect":[45.79791259765625,199.52857971191406,531.8843383789062,418.2669982910156],"size":15.997499465942383,"color":"#231815","family":"sans","align":"left","vertical":false},{"text":"Photographing Strangers","rect":[46.73391342163086,59.51397705078125,360.26947021484375,107.51397705078125],"size":48.0,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"05","rect":[172.32669067382812,138.46670532226562,234.6786346435547,186.46670532226562],"size":48.0,"color":"#000000","family":"serif","align":"left","vertical":false},{"text":"Who is the most fashionable?","rect":[974.0065307617188,815.1257934570312,1081.7901611328125,833.1257934570312],"size":18.0,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"Reflection: I returned to my hometown specifically to photograph its local life. The temple fair brought people of every age together. In earlier attempts to photograph strangers, I had approached people poorly: afraid to photograph faces directly, I made unremarkable images. This time, I deliberately sought scenes that revealed character and a story. Taking several photographs was also important. With people in motion, the best instant can only be caught as it happens.","rect":[626.9278564453125,493.6681213378906,873.0853271484375,819.1314697265625],"size":19.807498931884766,"color":"#004aad","family":"sans","align":"left","vertical":false},{"text":"Childhood on a rainbow slide","rect":[640,424,860,446],"size":16,"color":"#111111","family":"sans","align":"left","vertical":false},{"text":"Learning to fish starts young","rect":[924,424,1148,446],"size":16,"color":"#111111","family":"sans","align":"left","vertical":false}],"transcript":{"en":["At the annual temple fair, countless traders gather, eating and sleeping on site over ten days, from 23 November to 3 December. It is a carnival for small-goods sellers, and the liveliest place in my childhood memories.\n\nFor children, it is paradise: rows of ring-toss prizes, balloon-shooting stalls, fishing games and inflatable playgrounds. When play becomes tiring, there is sweet candyfloss, refreshing ice cream, candied hawthorn or fragrant Xinjiang barbecue.\n\nThe fair sells almost everything for daily life: pots and bowls, shoes and clothing, potted plants and household hardware…\n\nAlongside the stalls I remember, this year brought more “beauty stalls”: mole removal, eyebrow tattooing and wigs. Men and women, young and old, were happy to visit anything that promised to make them look better.","Photographing Strangers","05","Who is the most fashionable?","Reflection: I returned to my hometown specifically to photograph its local life. The temple fair brought people of every age together. In earlier attempts to photograph strangers, I had approached people poorly: afraid to photograph faces directly, I made unremarkable images. This time, I deliberately sought scenes that revealed character and a story. Taking several photographs was also important. With people in motion, the best instant can only be caught as it happens.","Childhood on a rainbow slide","Learning to fish starts young"],"zh":["在一年一度的庙会上，有无数商贩聚集，在11/23-12/3号连续十天里面，\n在这一块地方吃，在这一块地方睡。这是属于小商品商贩的狂欢，也是我\n童年记忆中最热闹的地方。\n这是孩子们的天堂，一排的套娃娃，一排的打气球，还有钓鱼、充气乐\n园；如果玩累了，你也可以去吃香甜的棉花糖、爽口的冰激凌、美味的糖\n葫芦抑或是香气四溢的新疆烧烤。\n你可以在这个会市里面找到用于生活方方面面的商品，锅碗瓢盆\n鞋子衣裤、盆栽作物、生活五金·……\n除了我记忆中的摊子，今年还多了许多“美容摊”，帮人点痣纹眉的，兜\n售假发的，对于可以让自己变美的摊子，男女老少都十分愿意光顾。","彩虹滑梯上的童年\n钓鱼要从小培养","给陌生人拍张照","05","谁是最时尚的人","实验心得：本次实验我特意\n回了一趟老家，想拍拍故乡\n的风土人情。恰逢庙会，男\n女老少便齐聚一堂了。在之\n前给陌生人的拍摄中，我对\n人物的把控完全错误，不敢\n拍正脸，照片没有独特性，\n本次实践，我特意聚焦可以\n展现人物特点和故事性的画\n面。多次按下快门也是一大\n关键，动态的人物只有抓拍\n才能找到最好的瞬间。"]}},{"number":11,"title":{"en":"Why this frame?","zh":"为什么选择它？"},"width":1190.25,"height":842.25,"boxes":[{"text":"Why this frame?","rect":[42.274803161621094,282.8308410644531,80.64342498779297,521.1555786132812],"size":38.99250030517578,"color":"#000000","family":"serif","align":"left","vertical":true},{"text":"1. Composition","rect":[400.6239318847656,52.90663146972656,463.87652587890625,82.5218505859375],"size":20.452499389648438,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"First image: The relationship between the person receiving the beauty treatment and the practitioner feels disconnected. The subject is partly cropped, while a blurred promotional poster fails to support the scene, making the frame cluttered and unfocused.\nSecond image: The face and treatment occupy the centre. Eye-themed advertising behind them echoes the procedure, possibly involving the brows or eyes, creating greater coherence.\n\n2. Focus","rect":[400.6239318847656,81.40663146972656,1110.2193603515625,253.5218505859375],"size":20.452499389648438,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"First image: Attention is scattered. The practitioner on the right is not a visual focus, while the main subject on the left is half cut off, leaving no clear visual guidance.\nSecond image: Clear gestures, a concentrated expression and working hands create a focal point and show the treatment in progress.\n\n3. Background and story","rect":[400.6239318847656,252.40663146972656,1110.2193603515625,396.0218505859375],"size":20.452499389648438,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"First image: A blurred poster of a figure in black has no direct connection to the subject and distracts from it.\nSecond image: Multiple eye close-ups in the backdrop directly relate to the treatment, strengthening both the narrative and the completeness of the setting.\n\n4. Colour and atmosphere","rect":[400.6239318847656,394.9066162109375,1110.2193603515625,538.5218505859375],"size":20.452499389648438,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"First image: Green and transparent objects, perhaps tools, intrude into the foreground without harmonising with the people or setting.\nSecond image: Purple bed linen establishes the main colour. The relationship between people and background is more harmonious, giving the scene warmth and professionalism.\n\n5. Narrative completeness","rect":[400.6239318847656,537.4066162109375,1110.2193603515625,681.0218505859375],"size":20.452499389648438,"color":"#000000","family":"sans","align":"left","vertical":false},{"text":"First image: Too few story details are provided for viewers to understand the situation quickly.\nSecond image: Action, expression and background form a coherent narrative sequence, conveying the treatment process and helping viewers enter the scene.","rect":[435.3934631347656,679.9066162109375,1110.2193603515625,766.5218505859375],"size":20.452499389648438,"color":"#000000","family":"sans","align":"left","vertical":false}],"transcript":{"en":["Why this frame?","1. Composition","First image: The relationship between the person receiving the beauty treatment and the practitioner feels disconnected. The subject is partly cropped, while a blurred promotional poster fails to support the scene, making the frame cluttered and unfocused.\nSecond image: The face and treatment occupy the centre. Eye-themed advertising behind them echoes the procedure, possibly involving the brows or eyes, creating greater coherence.\n\n2. Focus","First image: Attention is scattered. The practitioner on the right is not a visual focus, while the main subject on the left is half cut off, leaving no clear visual guidance.\nSecond image: Clear gestures, a concentrated expression and working hands create a focal point and show the treatment in progress.\n\n3. Background and story","First image: A blurred poster of a figure in black has no direct connection to the subject and distracts from it.\nSecond image: Multiple eye close-ups in the backdrop directly relate to the treatment, strengthening both the narrative and the completeness of the setting.\n\n4. Colour and atmosphere","First image: Green and transparent objects, perhaps tools, intrude into the foreground without harmonising with the people or setting.\nSecond image: Purple bed linen establishes the main colour. The relationship between people and background is more harmonious, giving the scene warmth and professionalism.\n\n5. Narrative completeness","First image: Too few story details are provided for viewers to understand the situation quickly.\nSecond image: Action, expression and background form a coherent narrative sequence, conveying the treatment process and helping viewers enter the scene."],"zh":["为\n什\n么\n选\n择\n它\n？","1. 构图","第一张：主体人物（正在接受美容操作的人）和美容师的关系显得比较割\n裂。人物被截掉了一部分，背景中模糊的宣传海报也缺乏对画面的呼应，显\n得杂乱且不够突出主题。\n第二张：人物的面部和操作动作占据画面中心，背景中的眼睛主题宣传布景\n与美容操作（可能是眉眼相关）形成呼应，增强了画面的主题感和连贯性。\n2. 画面聚焦","第一张：焦点分散，右侧美容师未成为视觉焦点，左侧主体被半裁，缺乏明\n确的视觉引导。\n第二张：美容师和客户的动作明确，美容师专注的表情和手部动作成为视觉\n中心，清晰展现了现场工作的状态。\n3. 背景与故事","第一张：背景中穿着黑色衣服的模糊人像宣传海报与主题无直接关联，甚至\n对画面造成干扰。\n第二张：背景布景中多张眼部特写与美容操作主题高度相关，使得画面更具\n有叙事性和场景的完整感。\n4. 色彩与氛围","第一张：绿色和透明的物品（可能是工具）在前景部分有些突兀，与人物和\n场景缺乏色彩上的协调。\n第二张：画面的主色调以紫色床单为主，人物和背景的色彩关系更为和谐，\n整体氛围温暖且专业。\n5. 叙事性与故事完整性","第一张：缺乏故事的细节描述，观者难以从画面中迅速理解情境。\n第二张：动作、表情、背景三者形成了较好的叙事链条，让观者能够感受到\n美容操作的具体过程，代入感更强。"]}},{"number":12,"title":{"en":"Documentary—Phoebe","zh":"新闻纪实——菲比"},"width":1190.25,"height":842.25,"boxes":[{"text":"Documentary Reporting","rect":[57.359344482421875,23.59980010986328,235.73561096191406,71.59980010986328],"size":48.0,"color":"#ffffff","family":"serif","align":"left","vertical":false},{"text":"06","rect":[115.36714935302734,96.26307678222656,177.72825622558594,144.26307678222656],"size":48.0,"color":"#ffffff","family":"serif","align":"left","vertical":false},{"text":"We interviewed her three times—19 November, 27 November and 16 December. Photographing led us into conversation, gradually building a fuller understanding of Auntie Phoebe and the experiences of someone who had first been a stranger.\n\nAt our last meeting, she began sharing news without waiting for questions: dinners that had continued into the early hours, a weekend visit to Qingshan Lake. That conversation also revealed that she was a single mother raising a son in high school.\n\nThe previous month, seventeen years after her earlier studies, she had taken an examination to progress from a college diploma to a bachelor’s degree. After just over a month’s preparation, she passed; two and a half years later, she would be able to receive her degree. “My son’s grades are poor, but I don’t mind,” she told me. “Poor grades don’t tell you everything, and they don’t mean my son is less capable than anyone else. Learning lasts a lifetime. I graduated with a college diploma, but you are never too old to learn. I have always wanted to keep studying.”\n\nShe lives by those words. She reads regularly, follows political and economic news, and never forces herself or her son down a prescribed path.\n\nShe has lived a varied life and has a calm outlook. When the pandemic hit the tourism industry in which she worked, she returned to Hangzhou to find a job. Seeing Zhejiang University recruiting campus drivers, she obtained the required licence and applied. She had been doing the job for more than two years. With her son at boarding school, her salary and rent from a property provided a comfortable living.\n\nPhoebe drives Route 3, the most complicated and longest route. Neither winter cold nor difficult road conditions make her lose her temper. She keeps an even mind, neither carried away by good fortune nor overwhelmed by setbacks.\n\nShe differs from a conventional image of motherhood: single, she smokes and drinks, yet she is a good mother, a committed employee and a capable woman. She gives her child room to grow and respect, works conscientiously without complaint, and supports herself without self-pity.\n\nShe is a vivid, modern woman.","rect":[634.1127319335938,413.17401123046875,1132.949951171875,774.5264892578125],"size":13.364999771118164,"color":"#ffffff","family":"sans","align":"left","vertical":false},{"text":"Vivid","rect":[536,400,580,575],"size":34,"color":"#000000","family":"serif","align":"left","vertical":true},{"text":"A modern woman","rect":[403,400,513,575],"size":32,"color":"#000000","family":"serif","align":"left","vertical":true}],"transcript":{"en":["Documentary Reporting","06","We interviewed her three times—19 November, 27 November and 16 December. Photographing led us into conversation, gradually building a fuller understanding of Auntie Phoebe and the experiences of someone who had first been a stranger.\n\nAt our last meeting, she began sharing news without waiting for questions: dinners that had continued into the early hours, a weekend visit to Qingshan Lake. That conversation also revealed that she was a single mother raising a son in high school.\n\nThe previous month, seventeen years after her earlier studies, she had taken an examination to progress from a college diploma to a bachelor’s degree. After just over a month’s preparation, she passed; two and a half years later, she would be able to receive her degree. “My son’s grades are poor, but I don’t mind,” she told me. “Poor grades don’t tell you everything, and they don’t mean my son is less capable than anyone else. Learning lasts a lifetime. I graduated with a college diploma, but you are never too old to learn. I have always wanted to keep studying.”\n\nShe lives by those words. She reads regularly, follows political and economic news, and never forces herself or her son down a prescribed path.\n\nShe has lived a varied life and has a calm outlook. When the pandemic hit the tourism industry in which she worked, she returned to Hangzhou to find a job. Seeing Zhejiang University recruiting campus drivers, she obtained the required licence and applied. She had been doing the job for more than two years. With her son at boarding school, her salary and rent from a property provided a comfortable living.\n\nPhoebe drives Route 3, the most complicated and longest route. Neither winter cold nor difficult road conditions make her lose her temper. She keeps an even mind, neither carried away by good fortune nor overwhelmed by setbacks.\n\nShe differs from a conventional image of motherhood: single, she smokes and drinks, yet she is a good mother, a committed employee and a capable woman. She gives her child room to grow and respect, works conscientiously without complaint, and supports herself without self-pity.\n\nShe is a vivid, modern woman.","Vivid","A modern woman"],"zh":["新闻纪实","06","           我们总共进行了三次采访-11/19、11/27与12/16，我们以拍摄带动采访，逐渐对菲比阿\n姨这个人有了更完整的认知，一点点地了解一个陌生人的经历。\n             最后一次采访的时候，不等我问，阿姨就熟稔地跟我分享自己的生活：上周经常聚餐\n到凌晨、周末去青山湖玩了等等，也是在这一次的聊天中我知道，她是一个单亲妈妈，独\n自抚养正在读高中的儿子。\n           上个月，时隔十七年的她去参加专升本考试，仅仅用了一个多月备考，她就通过了，\n两年半后，她就可以拿到本科证书了。她跟我说：“我儿子成绩很差，但我一点都不在\n乎，成绩差不能说明任何问题，也不能说明我儿子不如别人。相反，学习是一辈子的事\n情，我自己以前是专科毕业的，但是学到老活到老，我一直想继续读书。”\n           她是这样想的，也是这样做的。她保持阅读的习惯，她关注时政、经济新闻，她从不\n强迫自己或者儿子走上什么样的道路。\n           她有着精彩的人生和平和的心境。疫情期间，她从事的旅游行业受打击，回到老家杭\n州找工作，恰好看到浙大在招校内司机，就去考了特殊要求的驾照来应聘，已两年多了。\n现在儿子在寄宿学校，家里靠着她工作的工资和一套房子的收租也生活得不错。\n            菲比阿姨开的是三号线，是路线最复杂，时间最长的一条线路。不管是冬天的寒冷还\n是糟糕的路况，菲比阿姨从来都不动气更不会因物喜或以己悲。总是一颗平常心。\n              与传统的母亲形象不同，菲比阿姨单身、抽烟、喝酒，但她仍然是一个好妈妈，好\n员工，好女性。她给孩子足够的空间成长和足够的尊重，她工作时兢兢业业从不抱怨，她\n自力更生且从不自怨自艾。\n              她是鲜活的，现代的女性。","鲜\n活\n的","现\n代\n的\n女\n性"]}},{"number":13,"title":{"en":"Documentary—Field notes","zh":"新闻纪实——拍摄心得"},"width":1190.25,"height":842.25,"boxes":[{"text":"Reflection: This documentary exercise was a group assignment with two challenges. First, how could we show different perspectives when the three of us worked together and made similar photographs? Second, how could we establish news value? We focused on women working on campus, beginning with Phoebe, who drives a small campus shuttle, and then photographed several others. Interviews helped us uncover what was distinctive about each person.","rect":[320.0484924316406,28.967649459838867,607.404296875,169.2315673828125],"size":14.586939811706543,"color":"#ffffff","family":"sans","align":"left","vertical":false},{"text":"Dates: 19 Nov · 27 Nov · 16 Dec\nLocation: on campus\nSubject: Phoebe, campus shuttle driver","rect":[626.475341796875,19.265335083007812,906.6112060546875,101.72871398925781],"size":19.807498931884766,"color":"#ffffff","family":"sans","align":"left","vertical":false}],"transcript":{"en":["Reflection: This documentary exercise was a group assignment with two challenges. First, how could we show different perspectives when the three of us worked together and made similar photographs? Second, how could we establish news value? We focused on women working on campus, beginning with Phoebe, who drives a small campus shuttle, and then photographed several others. Interviews helped us uncover what was distinctive about each person.","Dates: 19 Nov · 27 Nov · 16 Dec\nLocation: on campus\nSubject: Phoebe, campus shuttle driver"],"zh":["实验心得：新闻纪实是小组作业，挑战有\n二：一是团队合作展现不同风貌，我们小组\n三人共同行动，照片也都大同小异；二是新\n闻纪实对新闻性的要求，我们聚焦校园中工\n作的女性，从开小白车的菲比阿姨开始，陆\n续拍了许多位女性。我们还通过采访来挖掘\n人物身上的独特之处，以此体现新闻性。","拍摄时间：11/19  11/27 12/16\n拍摄地点：校内\n拍摄人物：小白车司机菲比"]}},{"number":14,"title":{"en":"The outtakes","zh":"废片集"},"width":1190.25,"height":842.25,"boxes":[{"text":"The Outtakes","rect":[60.025421142578125,533.3442993164062,193.36927795410156,581.3442993164062],"size":48.0,"color":"#ffffff","family":"serif","align":"left","vertical":false},{"text":"07","rect":[95.52151489257812,621.0638427734375,157.8734588623047,669.0638427734375],"size":48.0,"color":"#ffffff","family":"serif","align":"left","vertical":false},{"text":"Reflections on outtakes: Sometimes the theme did not fit; sometimes the frame was cluttered, the focus wrong, the exposure too strong, or the image soft. Sometimes it was the colour, the composition, or simply repetition…","rect":[696.0409545898438,584.4052734375,1099.3009033203125,777.3574829101562],"size":27.802499771118164,"color":"#ffffff","family":"serif","align":"left","vertical":false},{"text":"Not wasted frames","rect":[1004,176,1063,420],"size":40,"color":"#ffffff","family":"serif","align":"left","vertical":true},{"text":"The path that brought me here","rect":[915,176,974,450],"size":35,"color":"#ffffff","family":"serif","align":"left","vertical":true}],"transcript":{"en":["The Outtakes","07","Reflections on outtakes: Sometimes the theme did not fit; sometimes the frame was cluttered, the focus wrong, the exposure too strong, or the image soft. Sometimes it was the colour, the composition, or simply repetition…","Not wasted frames","The path that brought me here"],"zh":["废片集","07","废片心得：或者因不符合主题、\n或者因画面杂乱、或者因对焦错\n误、或者因曝光太强、或者因虚\n焦、或者因色调、或者因构图、\n或者因重复……","不\n是\n废\n片","是\n来\n时\n路"]}},{"number":15,"title":{"en":"The outtakes—Contact sheet","zh":"废片集——照片拼贴"},"width":1190.25,"height":842.25,"boxes":[],"transcript":{"en":[],"zh":[]}},{"number":16,"title":{"en":"Afterword","zh":"后序"},"width":1190.25,"height":842.25,"boxes":[{"text":"As the semester draws to a close, so does our Photojournalism course. Looking back, we have gained a great deal: not only basic photographic techniques and skills, but also a sharper news sense and stronger powers of observation through practice.","rect":[636.2341918945312,132.74609375,1101.9896240234375,241.6382598876953],"size":19.40999984741211,"color":"#ffffff","family":"sans","align":"left","vertical":false},{"text":"Making this booklet brought us back to our work. Every time we turn the pages, we return to those days of photographing. The frozen moments and the stories behind them remind us of photojournalism’s appeal and its responsibilities.","rect":[636.2341918945312,267.74609375,1101.9896240234375,376.6382751464844],"size":19.40999984741211,"color":"#ffffff","family":"sans","align":"left","vertical":false},{"text":"Thank you to our teachers for their careful guidance and patient feedback. Your support helped us move further and more confidently along this path. Thank you also to our classmates for their encouragement: your company made the learning journey less solitary.","rect":[636.2341918945312,402.74609375,1101.9896240234375,511.6382751464844],"size":19.40999984741211,"color":"#ffffff","family":"sans","align":"left","vertical":false},{"text":"Looking ahead, we hope to carry the spirit of photojournalism forward, using our cameras to capture social change and light and shadow to convey the feeling of our times. May this booklet become a milestone along that path. We look forward to making more accomplished work and contributing to society’s progress.","rect":[636.2341918945312,537.7461547851562,1101.9896240234375,673.6383056640625],"size":19.40999984741211,"color":"#ffffff","family":"sans","align":"left","vertical":false},{"text":"My story with photojournalism is still unfolding…","rect":[636.2341918945312,699.7461547851562,869.1137084960938,727.6383056640625],"size":19.40999984741211,"color":"#ffffff","family":"sans","align":"left","vertical":false},{"text":"Afterword—A few closing thoughts","rect":[664.314453125,37.6889762878418,1008.5463256835938,79.68898010253906],"size":42.0,"color":"#ffffff","family":"serif","align":"left","vertical":false}],"transcript":{"en":["As the semester draws to a close, so does our Photojournalism course. Looking back, we have gained a great deal: not only basic photographic techniques and skills, but also a sharper news sense and stronger powers of observation through practice.","Making this booklet brought us back to our work. Every time we turn the pages, we return to those days of photographing. The frozen moments and the stories behind them remind us of photojournalism’s appeal and its responsibilities.","Thank you to our teachers for their careful guidance and patient feedback. Your support helped us move further and more confidently along this path. Thank you also to our classmates for their encouragement: your company made the learning journey less solitary.","Looking ahead, we hope to carry the spirit of photojournalism forward, using our cameras to capture social change and light and shadow to convey the feeling of our times. May this booklet become a milestone along that path. We look forward to making more accomplished work and contributing to society’s progress.","My story with photojournalism is still unfolding…","Afterword—A few closing thoughts"],"zh":["随着本学期的结束，我们的《新闻摄影》课程也即将画\n上圆满的句号。回顾这段学习历程，我们收获颇丰，不\n仅掌握了新闻摄影的基本技术与技巧，更在实践中锻炼\n了自己的新闻敏感性和观察力。","在实验册子的制作过程中，我们再次回顾了自己的作\n品，每一次翻阅都仿佛回到了那些拍摄的日子。那些定\n格的瞬间，那些背后的故事，都让我们深感新闻摄影的\n魅力与责任。","感谢老师的悉心指导与耐心点评，是您的引导让我们在\n新闻摄影的道路上越走越远，越走越坚定。同时，也要\n感谢同学们的相互鼓励与支持，是你们的陪伴让我们的\n学习之旅不再孤单。","展望未来，我们将继续秉承新闻摄影的精神，用镜头捕\n捉社会的变迁，用光影传递时代的温度。愿这本实验册\n子能够成为我们新闻摄影道路上的一个重要里程碑，也\n期待在未来的日子里，我们能够创作出更多优秀的新闻\n摄影作品，为社会的进步与发展贡献自己的力量。","我与新闻摄影未完待续……","后序—写在后面的话"]}}];
